{"function":"() => {
const out = {};
const q = s => [...document.querySelectorAll(s)];
// tabs
out.tabs = q('nav[aria-label="Abas de Navegação Simples"] button, nav[aria-label="Abas de Navegação Simples"] li').map(e => ({tag:e.tagName, cls:e.className, role:e.getAttribute('role'), sel:e.getAttribute('aria-selected'), cur:e.getAttribute('aria-current'), txt:e.textContent.trim()}));
out.tabNav = document.querySelector('nav[aria-label="Abas de Navegação Simples"]')?.outerHTML.slice(0,1500);
// filters
out.filters = q('pnip-filter-panel [class*=cursor], pnip-filter-panel div').filter(e=>getComputedStyle(e).cursor==='pointer').slice(0,8).map(e=>({tag:e.tagName, cls:e.className, tabindex:e.getAttribute('tabindex'), role:e.getAttribute('role'), txt:e.textContent.trim().slice(0,30)}));
out.pastel = q('.primary-pastel-01').map(e=>({tag:e.tagName, html:e.outerHTML.slice(0,300), parent:e.parentElement.outerHTML.slice(0,300)}));
out.orange = q('*').filter(e=>getComputedStyle(e).backgroundColor==='rgb(255, 140, 0)').map(e=>e.outerHTML.slice(0,300));
out.h = q('h1,h2,h3,h4,h5,h6').map(e=>e.tagName+':'+e.textContent.trim());
out.landmarks = q('header,nav,main,footer,[role=banner],[role=navigation],[role=main],[role=contentinfo]').map(e=>e.tagName+'|'+e.getAttribute('role')+'|'+e.getAttribute('aria-label'));
return out;
}"}

